//! Encoded ingest fixtures shared by MPEG-TS, SRT, and CMAF tests.

use base64::{Engine as _, engine::general_purpose::STANDARD};

/// Matroska/WebM EBML header. SRT MPEG-TS ingest refuses this prefix so a
/// publisher cannot silently send the wrong container.
pub fn ebml_header() -> Vec<u8> {
    vec![0x1a, 0x45, 0xdf, 0xa3, 0x01, 0x00, 0x00, 0x00]
}

/// Short H.264 and ADTS-AAC MPEG-TS used to pin packet adaptation.
///
/// Generated once with:
/// `ffmpeg -f lavfi -i testsrc2=size=64x64:rate=10:duration=0.12 -f lavfi -i sine=frequency=1000:sample_rate=48000:duration=0.12 -map 0:v:0 -map 1:a:0 -c:v libx264 -preset ultrafast -tune zerolatency -profile:v baseline -level:v 3.0 -g 10 -keyint_min 10 -sc_threshold 0 -bf 0 -b:v 24k -c:a aac -b:a 24k -shortest -f mpegts h264-aac.ts`
const H264_ADTS_AAC_MPEG_TS_BASE64: &str = "";

pub fn h264_adts_aac_mpeg_ts() -> Vec<u8> {
    STANDARD
        .decode(H264_ADTS_AAC_MPEG_TS_BASE64)
        .expect("checked-in fixture base64 is valid")
}
